        ) VALUES (
            'f1cc1c80-f89b-58f9-8a97-85ff787a6ed6', 'res-keben-0154', 'book', '数学 湘教版 选择性必修 第一册 2019版', '湘教版 高中', '人之初，学数数，一二三，四五六，先后顺序要背熟。按先后顺序排成的一列数就是数列。儿时的我们进入数学之门的第一课就是数列。每次加一，这是等差数列。芝麻开花节节高，如果每一节增长的高度相等，各节高度也组成等差数列。细胞的繁殖，不是每秒增加同样数目，而是细胞个数每秒增长同样倍数，这是等比数列。钢琴从左到右每个键发音频率依次升高，每次乘一个常数，也是等比数列。',
            'senior', '高中', '选择性必修', '数学', '湘教版', '', '',
            'https://image.xuebaw.com/covers/textbook/0154.webp', 'PDF', '138.3 MB', 218,
            654, 436, true, true,
            '{"source": "keben.app", "keben_id": "0154", "matched_key": "高中/数学"}'::jsonb, '[]'::jsonb, NOW(), NOW()
        )
