        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            'df2a8126-8bbb-5d10-965c-d119b546b44c', 'res-keben-0333', 'book', '数学 北京版 八年级 上册 2024版', '北京版 八年级', '你知道第一次数学危机吗？有理数不够用了，它的兄弟—无理数横空出世，“数的家族”扩充至“实数”．相应的，“式的家族”也有了新成员—根式．从数学系统的完备性考虑，有了新的体系以后，原有的支撑体系是否可以继续沿用呢？一路走来，我们一直在进行“数”与“式”的对比．在欢迎“式的家族”新成员之前，还需要研究另一位成员—分式．那么，对分数的研究方法能沿用到分式身上吗？',
            'junior', '八年级', '上册', '数学', '北京版', '', '',
            'https://image.xuebaw.com/covers/textbook/0333.webp', 'PDF', '4.9 MB', 169,
