        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '9574f926-14e4-5490-ae4a-12abbe43090f', 'res-keben-0508', 'book', '物理 苏科版 八年级 上册 2022版', '苏科版 八年级', '欢迎步入奇妙的物理世界！在小学科学课程中，我们已经接触了水、空气以及各种奇特的物质，知道了物体是运动的，物体运动状态的改变与力有关，对声、光、热、电等现象进行了初步探索……你知道吗，这些都是物理学研究的内容。物理学是研究物质结构、相互作用和运动规律的一门基础学科。它能引领我们科学地认识自然，解决实际问题，认识科学、技术、社会、环境之间的关系。',
            'junior', '八年级', '上册', '物理', '苏科版', '', '',
