        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '08623211-460a-52fb-ae92-d1bccff60ab3', 'res-keben-0730', 'book', '科学 武汉社版 九年级 下册 2022版', '武汉社版 九年级', '周末，你坐在电脑前，在一页页网页间查阅资料；你打算下午约朋友出去逛公园，于是你拿起电话……当这些发生的时候，你可曾意识到，科学技术无时无刻不在影响我们的生活。进入新世纪以来，科学技术有了飞跃的发展，我们的生活也发生了巨大的变化。在科技使得人类社会异彩纷呈的同时，我们还要关注哺育我们的地球母亲，她是我们赖以生存的家园，她孕育出辉煌灿烂的文明。我们人类所赖以生存的一切资源，都是地球母亲的恩赐。',
            'junior', '九年级', '下册', '科学', '武汉社版', '', '',
