        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '7b453629-eeb6-5d29-ba33-e5d5886ffd3f', 'res-keben-0882', 'book', '美术 鲁美版 选择性必修 第三册 2022版', '鲁美版 高中', '雕塑是一门古老的造型艺术。当原始先民在一块石头或兽骨上敲击、刻画、钻孔，或信手将一块陶土捏塑成某个形象时，人类就开始了对形体与空间关系的探索。雕塑具有自身的艺术特质：雕塑有一定的体量并占据相应的空间，具有真实的立体感；雕塑之美与其材质相关，玉石的细腻、青铜的凝重、木质的温润、陶土的朴拙，给人以丰富的美感享受；雕塑是“凝固的旋律”，它相对固定和恒久，可谓寓动于静、定格一瞬、展示永恒。雕塑的艺术感染力是强烈而深刻的。',
            'senior', '高中', '选择性必修', '美术', '鲁美版', '', '',
            'https://image.xuebaw.com/covers/textbook/0882.webp', 'PDF', '146.0 MB', 61,
            183, 122, true, true,
            '{"source": "keben.app", "keben_id": "0882", "matched_key": "高中/美术"}'::jsonb, '["第 1 课 雕塑的基本特点", "第 2 课 如何鉴赏雕塑作品", "第 3 课 传统与写实", "第 4 课 意象与表现", "第 5 课 民间雕塑与生活", "第 6 课 现代抽象雕塑", "第 7 课 浮雕与透雕"]'::jsonb, NOW(), NOW()
        )
