            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            'c4bfd687-b43d-52f2-944d-f7ef49cb1abf', 'res-keben-1042', 'book', '艺术·舞蹈 人教版 影视（含数字媒体艺术） 九年级 上册 2022版', '人教版 九年级', '影视（含数字媒体艺术）作为艺术课程的重要组成部分，把影视和数字媒体艺术的学习内容、思维方式与创作方法整合到一起，向我们展示了一个全新的世界。优秀的影视作品可以涵养我们的心灵，提升我们的审美素养，培植我们对党和国家的无限热爱以及坚定的理想信念，帮助我们形成健康积极的人生观和价值观；优秀的影视作品也可以引导我们解决问题、热爱生活、创造生活。',
            'junior', '九年级', '上册', '艺术·舞蹈', '人教版', '', '',
