            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '3e4c7920-2801-5131-9fd1-6a206a45b623', 'res-keben-1093', 'book', '艺术·舞蹈 西南大学版 影视（含数字媒体艺术） 八年级 上册 2022版', '西南大学版 八年级', '大家现在翻开的是一册全新的《艺术影视（含数字媒体艺术）》教材。在学习过音乐、美术等艺术课程之后，一门独特的、综合多种艺术特点的新艺术——影视艺术向大家敞开大门。让我们一起翱翔于艺术审美的大千世界，尽情欣赏精彩纷呈的优秀影视作品，充分享受视听的盛宴。本套教材遵循立足中国、融汇世界的原则，秉持循序渐进、螺旋上升的理念。',
            'junior', '八年级', '上册', '艺术·舞蹈', '西南大学版', '', '',
            'https://image.xuebaw.com/covers/textbook/1093.webp', 'PDF', '52.9 MB', 81,
            243, 162, true, true,
            '{"source": "keben.app", "keben_id": "1093", "matched_key": "初中/八年级"}'::jsonb, '["电影《建党伟业》", "电视剧《长征》", "电影《平原游击队》", "电影《南征北战》", "电影《建国大业》", "实践与运用一", "第一单元革命传承", "电影《孔子》", "纪录片《从秦始皇到汉武帝》", "纪录片《我在故宫修文物》"]'::jsonb, NOW(), NOW()
        )
