        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '6d97fb1e-a784-5e3f-a454-8e8bae7891aa', 'res-keben-1095', 'book', '艺术·舞蹈 西南大学版 舞蹈 八年级 上册 2022版', '西南大学版 八年级', '本教材坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻党的教育方针，遵循教育教学规律，落实立德树人根本任务，发展素质教育。以“培养什么人、怎样培养人、为谁培养人”为核心问题导向，坚持以美育人、以舞塑人、以艺化人。反映时代特征，努力构建具有中国特色、世界水准的义务教育舞蹈课程体系。',
            'junior', '八年级', '上册', '艺术·舞蹈', '西南大学版', '', '',
            'https://image.xuebaw.com/covers/textbook/1095.webp', 'PDF', '46.9 MB', 81,
            243, 162, true, true,
            '{"source": "keben.app", "keben_id": "1095", "matched_key": "初中/八年级"}'::jsonb, '["第一单元雪域高原上的藏族舞蹈", "第 1 课舞蹈《翻身农奴把歌唱》", "第 2 课地域风俗与藏族舞蹈", "第 3 课风格性组合“弦子”", "第 4 课舞蹈小品《北京的金山上》", "单元荟萃", "辽阔草原上的蒙古族舞蹈第二单元", "第 1 课舞蹈《浪漫草原》", "第 2 课地域风俗与蒙古族舞蹈", "第 3 课风格性组合“鸿雁”", "第 4 课舞蹈小品《行雁走马》", "单元荟萃", "七彩天山间的维吾尔族舞蹈第三单元", "第 1 课舞蹈《掀起你的盖头来》", "第 2 课地域风俗与维吾尔族舞蹈", "第 3 课风格性组合“赛乃姆”", "第 4 课舞蹈小品《瓜蔓株连果甜香》", "单元荟萃", "白山黑水间的朝鲜族舞蹈第四单元", "第 1 课舞蹈《谷雨》", "第 2 课地域风俗与朝鲜族舞蹈", "第 3 课风格性组合“古格里长短”", "第 4 课舞蹈小品《柳手鹤步》", "单元荟萃"]'::jsonb, NOW(), NOW()
