        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '67eae4f8-0e98-53e9-8f84-e2b3b0bb5c65', 'res-keben-1096', 'book', '艺术·舞蹈 赣美版 戏剧（含戏曲） 八年级 上册 2022版', '赣美版 八年级', '年轻的你，一定听说过戏剧。在人类数千年的文明演进中，戏剧以其独特的艺术魅力，通过展现或表达冲突、情感与奇思妙想，深深地触动着观众的心灵，带给观众愉悦与震撼。正是这份独特的艺术价值，使得戏剧赢得了古今中外无数人的喜爱。此刻，让我们一同推开戏剧之门，共同探索戏剧的艺术世界吧！本套教材秉承“做中学”“用中学”“创中学”的教学理念，致力于培养同学们的核心素养。',
