        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '24a3fece-3a4b-5b95-987d-59f695cbf8cb', 'res-keben-1110', 'book', '语文·书法练习指导 人美版 实验 三年级 上册 2022版', '人美版 三年级', '你知道吗，我国是一个拥有五千年灿烂文明的古国，汉字的书写艺术是祖国文化艺术百花园中的一朵奇葩。今天，我们编写的《书法练习指导》将开启你愉快而有趣的书法学习之旅，让你感受书法艺术的无穷魅力，了解中国传统文化的丰富内涵。《书法练习指导》分为“书写指导”“集字练习”“读碑赏帖”“书法园地”四大部分。',
            'primary', '三年级', '上册', '语文·书法练习指导', '人美版', '', '',
