        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '7ee8ae18-6dc7-5ffa-9970-4c0d6280fff5', 'res-keben-1273', 'book', '艺术·美术 冀美版 一年级 下册 2022版', '冀美版 一年级', '本教科书旨在开启大家对美的感知与创造，陪伴同学们在美术世界中快乐探索、茁壮成长。在这里，大家可以用色彩讲述心情，用图画记录生活，尽情释放天性，感知世界和人类文化宝库的丰富和多彩。教科书精心设置有若干单元，从各种动物到身边的日常物品，从春日美景到优秀传统文化，我们将在一个个好玩有趣的造型活动中，体会和理解点、线、面、形、色等元素的内涵，并学会用画笔记录、表达情感与思考……在一次次快乐的欣赏、表现、想象、创造和探索中，逐步熟悉美术的世界，…',
            'primary', '一年级', '下册', '艺术·美术', '冀美版', '', '',
            'https://image.xuebaw.com/covers/textbook/1273.webp', 'PDF', '206.4 MB', 56,
            168, 112, true, true,
            '{"source": "keben.app", "keben_id": "1273", "matched_key": "小学/一年级"}'::jsonb, '[]'::jsonb, NOW(), NOW()
        )
