        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '7d6b2960-937e-5bb9-9bf2-d2dca3ebd0cf', 'res-keben-1361', 'book', '艺术·美术 湘美版 九年级 上册 2022版', '湘美版 九年级', '达·芬奇、拉斐尔、米开朗基罗……是什么样的时代造就了这么多杰出的艺术家？在没有摄影之前人们一直用绘画技术留住美好的瞬间，有了摄影之后呢？摄影与绘画有哪些相通之处？建筑作为美术的一个门类，我们该如何看待它呢……美术世界是如此广阔，在这个学期的学习中，我们将在更大的范围内探究美术世界，我们将学习文艺复兴时期的艺术；学习摄影的基础知识；欣赏不同地域和历史条件下不同的建筑风格，思考建筑的审美、文化价值以及它与环境和人的关系；我们还会分析中外绘…',
            'junior', '九年级', '上册', '艺术·美术', '湘美版', '', '',
            'https://image.xuebaw.com/covers/textbook/1361.webp', 'PDF', '17.2 MB', 52,
            156, 104, true, true,
            '{"source": "keben.app", "keben_id": "1361", "matched_key": "初中/九年级"}'::jsonb, '["第1课走下神坛", "第2课瞬间的精彩", "第3课画“说”空间", "第4课我们在一起", "第5课门", "第6课魅力永恒的建筑", "第7课美丽家园", "美术作品概览（五）"]'::jsonb, NOW(), NOW()
        )
        ON CONFLICT (slug) DO UPDATE SET
            title = EXCLUDED.title,
