        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '36d8d136-d5f6-5f91-8965-6bf1615c6fdb', 'res-keben-1607', 'book', '艺术·音乐 沪教版 七年级 下册 2022版', '沪教版 七年级', '音乐是一门声音的艺术。它起源于劳动，反映社会生活；它用音乐的语言，引发联想和想象；它与社会同步发展，表达人们的思想情感。音乐艺术的产生是人类智慧的结晶，同时影响人的思维方式，陶冶人的性情品格。因而，音乐的学习对于我们每一个人的成长和发展都是非常重要的。',
            'junior', '七年级', '下册', '艺术·音乐', '沪教版', '', '',
            'https://image.xuebaw.com/covers/textbook/1607.webp', 'PDF', '40.7 MB', 74,
            222, 148, true, true,
