            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '9e50269e-5eca-52e3-9628-cf189448786b', 'res-keben-1694', 'book', '艺术·音乐 西南大学版 九年级 上册 2022版', '西南大学版 九年级', '合着梦幻的节拍，哼着快乐的曲调，一张张揭去的日历已悄悄将你送上多姿多彩的初三。打开你手中这册音乐书吧！憨憨的熊猫伴随着串串音符，会令你心驰神往；曲苑中的小曲、唱段，会带给你舒心的欢笑；茶山飞舞的彩蝶，将引发你无尽的遐想；欧罗巴的歌声，仿佛令你置身于美丽的异域他乡。',
            'junior', '九年级', '上册', '艺术·音乐', '西南大学版', '', '',
