        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            'da11033c-af64-56ce-8910-2fbbdb5f1a9a', 'res-keben-1697', 'book', '艺术·音乐 西南大学版 五年级 上册 2022版', '西南大学版 五年级', '你喜欢旅行吗？搭上火车、乘上飞机，去饱览自然的美景，领略形态各异的风土人情，观赏巧夺天工的建筑……现在，让音乐伴随着我们一起去旅行吧！当我们相聚在北京，《北京童谣》会在你耳边回响; 走进神奇的巴蜀大地，《山娃娃》会领你去细细品味巴蜀之声; 踏上美丽的大草原，悠扬的《牧歌》、激烈的《赛马》、绿色的草地让你仿佛置身于天堂。',
            'primary', '五年级', '上册', '艺术·音乐', '西南大学版', '', '',
