        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '9d992973-5cbc-5c6e-a4ae-f33b87608631', 'res-keben-1698', 'book', '艺术·音乐 西南大学版 五年级 下册 2022版', '西南大学版 五年级', '你跳过竹竿舞吗？欢快活泼的节奏，特有的民族旋律，吸引着我们加入跳竹竿舞的队列。你去过节日的天山吗？《新疆之春》那悠扬的旋律、跳跃的节奏，一定会将你带进新疆歌舞的海洋，《戈壁骑兵》在广阔无垠的沙漠上留下了一个又一个动人故事。我们一直在讲节奏、旋律，这应该是你们非常熟悉的两个词儿！人们说“节奏是音乐的骨骼，旋律是音乐的灵魂”，当不同的节奏和旋律组合在一起的时候，音乐就产生了无穷的魅力……',
            'primary', '五年级', '下册', '艺术·音乐', '西南大学版', '', '',
