        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '75208708-366d-5dac-8386-e75b887b1dda', 'res-keben-1700', 'book', '艺术·音乐 西南大学版 六年级 上册 2022版', '西南大学版 六年级', '“夫乐者，乐也，人情之所必不免也，故人不能无乐。”这是两千多年前中国哲学家荀子的一句名言。“不懂得音乐的人，不算是一个真正的人。”这是德国文学家歌德的警句。可见音乐对于人有着十分重要的意义。在悠扬的乐声中，我们将踏上五彩丝路，快乐的《小号手》将带你步入管乐之家；形式多样的流行音乐，将引领你走进现代音乐的世界。让我们置身于那迷人的音响世界中，不断欣赏、品味，也许你也会达到孔夫子闻《韶》乐后“三月不知肉味”的那种忘我境界呢！',
            'primary', '六年级', '上册', '艺术·音乐', '西南大学版', '', '',
            'https://image.xuebaw.com/covers/textbook/1700.webp', 'PDF', '55.2 MB', 66,
            198, 132, true, true,
            '{"source": "keben.app", "keben_id": "1700", "matched_key": "小学/六年级"}'::jsonb, '["第一单元山寨传声", "迷人的山寨", "欣赏彝族舞曲", "竹林深处", "唱歌节日的夜晚", "欢乐的山寨", "欣赏欢乐的芦笙", "唱歌瑶山乐", "葫芦丝吹奏", "欣赏阳光羌娃"]'::jsonb, NOW(), NOW()
        )
