            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '9032751d-5c22-5522-b580-d6933c61dcb4', 'res-keben-1926', 'book', '英语 沪教版 三年级起点 四年级 下册 2022版', '沪教版 四年级', '经过一段时间的学习，同学们已经可以用英语介绍自己、家人和朋友身边的事物了。从开始的生涩、缓慢到渐渐的自如、流畅，是不是觉得很有趣、很兴奋呢？可是，你们一定也会有这样的感觉：新学的那点儿英语实在不能满足表达的需要。到了一个新地方，遇到一件好玩的事，想发一下感叹，却找不到合适的词语或句式。其实，这都是很正常的现象，因为你们心智的成长与英语学习的程度不成比例。不要着急，这是除了母语以外，学习任何一门语言都必然会碰到的问题。',
            'primary', '四年级', '下册', '英语', '沪教版', '', '',
            'https://image.xuebaw.com/covers/textbook/1926.webp', 'PDF', '13.0 MB', 78,
            234, 156, true, true,
            '{"source": "keben.app", "keben_id": "1926", "matched_key": "小学/四年级"}'::jsonb, '[]'::jsonb, NOW(), NOW()
        )
