        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '0517b38f-92f5-5cbb-9734-c238e2052da5', 'res-keben-1958', 'book', '英语 湘少版 三年级起点 五年级 上册 2022版', '湘少版 五年级', '同学们，欢迎你们来到英语学习课堂！同学们已经学习了一些英语，从现在开始要进入一个新的学习阶段。在低年级学习阶段，我们通过有趣的听做、说唱、玩演等活动来学习英语；到了中高年级，课本中将逐步增加读和写的活动，以此来进一步培养我们读写英语的能力。在本册课本中，同学们将学习到更多的用英语表达人物相貌、中外食品、日常活动、兴趣爱好、农历春节等的方法。学习的知识更多了，要求也更高了，因此同学们要更努力地多听、多读。',
            'primary', '五年级', '上册', '英语', '湘少版', '', '',
