        INSERT INTO resources (
            id, slug, channel_slug, title, subtitle, description,
            stage, grade, term, subject, edition, region, school,
            cover_image, file_type, file_size, page_count,
            view_count, save_count, is_recommended, is_published,
            extra_metadata, file_tree, created_at, updated_at
        ) VALUES (
            '0865dfc4-49a5-51c5-a0b2-f3cd38ceca3d', 'res-keben-1995', 'book', '英语 译林版 三年级 上册 2022版', '译林版 三年级', '欢迎来到英语学习的乐园。从三年级开始，你们就要正式学习英语啦！英语是世界上使用非常广泛的语言，学好英语不仅可以帮助你们了解不同文化，树立国际视野，还能帮助你们把祖国的优秀文化介绍给全世界！英语学习跟生活息息相关。在本册教材里，你们将和杨玲、苏海、王兵、刘涛等小朋友一起学习如何礼貌地用英语打招呼，询问新同学的姓名，向别人介绍自己的朋友和家人，等等。你们还将和同伴一起参与综合语言实践项目，制作自己专属的姓名牌和家庭成员小海报。',
            'primary', '三年级', '上册', '英语', '译林版', '', '',
